@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Amie Pastel — light, playful, multicolor calendar app.
 *
 * Authored from the Amie product frames: a soft off-white ground, friendly
 * rounded shapes (generous radius), and a palette of soft pastel hues used as
 * event/category colors (pink, blue, green, yellow, lavender). The material is
 * pillowy and gentle: low-contrast soft shadows, a faint top sheen on raised
 * surfaces, a faint inset on recessed controls. No grain, no hard edges.
 *
 * Primary is the soft green that lights Amie's active toggles. The other
 * pastels become badge variants and the chart palette.
 *
 * Per repo rule every color is oklch(), including inside shadow stacks.
 */

:root {
  /* ─── Surfaces: soft off-white ground, white cards ─── */
  --background: oklch(0.984 0.004 95);       /* warm off-white page */
  --foreground: oklch(0.29 0.018 285);       /* soft ink, gentle cool charcoal */

  --card: oklch(1 0 0);                       /* white card */
  --card-foreground: oklch(0.29 0.018 285);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.29 0.018 285);

  /* ─── Primary: soft Amie green (the active-toggle pastel) ─── */
  --primary: oklch(0.855 0.094 152);
  --primary-foreground: oklch(0.34 0.072 153);

  /* Secondary: soft warm-gray surface button */
  --secondary: oklch(0.965 0.005 95);
  --secondary-foreground: oklch(0.35 0.018 285);

  --muted: oklch(0.962 0.005 95);
  --muted-foreground: oklch(0.55 0.015 285);

  --accent: oklch(0.93 0.04 152);             /* soft green tint hover */
  --accent-foreground: oklch(0.34 0.072 153);

  --destructive: oklch(0.71 0.15 18);         /* soft coral red */
  --destructive-foreground: oklch(0.99 0 0);
  --success: oklch(0.71 0.112 150);
  --success-foreground: oklch(0.29 0.018 285);
  --warning: oklch(0.85 0.112 75);
  --warning-foreground: oklch(0.29 0.018 285);

  --border: oklch(0.92 0.006 285);
  --input: oklch(0.995 0.002 95);
  --ring: oklch(0.78 0.11 152);               /* green focus ring */
  --radius: 1rem;                              /* 1rem: friendly, generous rounding */

  /* ─── Pastel palette: Amie's event/category hues ─── */
  --pastel-pink: oklch(0.86 0.075 12);
  --pastel-pink-foreground: oklch(0.44 0.11 14);
  --pastel-blue: oklch(0.85 0.07 245);
  --pastel-blue-foreground: oklch(0.45 0.11 252);
  --pastel-green: oklch(0.87 0.082 152);
  --pastel-green-foreground: oklch(0.42 0.1 153);
  --pastel-yellow: oklch(0.92 0.085 95);
  --pastel-yellow-foreground: oklch(0.5 0.1 80);
  --pastel-lavender: oklch(0.85 0.07 300);
  --pastel-lavender-foreground: oklch(0.46 0.12 300);

  /*
   * ─── Shadow scale ───
   * Soft, low-contrast, far-throwing ambient pools over a faint top sheen.
   * Light theme so the ambient is a gentle cool-ink wash (5-18% alpha), never
   * the heavy 40-60% black of a dark DS. Higher tiers throw farther + softer.
   */
  --shadow-xs:
    0 0.0625rem 0.125rem oklch(0.29 0.018 285 / 0.06);

  --shadow-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.6),
    0 0.0625rem 0.125rem oklch(0.29 0.018 285 / 0.05),
    0 0.1875rem 0.5rem -0.125rem oklch(0.29 0.018 285 / 0.07);

  --shadow-md:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.6),
    0 0.125rem 0.25rem oklch(0.29 0.018 285 / 0.06),
    0 0.5rem 1.25rem -0.25rem oklch(0.29 0.018 285 / 0.1);

  --shadow-lg:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.6),
    0 0.5rem 1.125rem -0.25rem oklch(0.29 0.018 285 / 0.1),
    0 1.125rem 2.5rem -0.625rem oklch(0.29 0.018 285 / 0.14);

  --shadow-xl:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.6),
    0 1rem 2rem -0.5rem oklch(0.29 0.018 285 / 0.12),
    0 1.875rem 3.75rem -1rem oklch(0.29 0.018 285 / 0.18);

  /* Aliases used directly by component class strings ([box-shadow:var(--shadow-s)] etc). */
  --shadow-s: var(--shadow-sm);
  --shadow-m: var(--shadow-md);
  --shadow-l: var(--shadow-lg);

  /* Inset/pressed: inputs sit gently recessed (soft pocket), faint not harsh. */
  --shadow-inset:
    inset 0 0.0625rem 0.125rem oklch(0.29 0.018 285 / 0.07),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.5);

  /* Default raised control (soft pillow tab). */
  --shadow-button:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.7),
    0 0.0625rem 0.125rem oklch(0.29 0.018 285 / 0.06),
    0 0.1875rem 0.5rem -0.125rem oklch(0.29 0.018 285 / 0.08);

  --shadow-button-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.8),
    0 0.125rem 0.25rem oklch(0.29 0.018 285 / 0.07),
    0 0.375rem 1rem -0.1875rem oklch(0.29 0.018 285 / 0.12);

  /* Primary pillow: soft green fill. Bright inset top highlight + a soft green
     ambient glow, the material reused by every filled control (checkbox checked,
     switch track, radio dot, slider range) so they read as one pillow. */
  --shadow-primary:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.55),
    inset 0 -0.0625rem 0.0625rem oklch(0.34 0.072 153 / 0.12),
    0 0.0625rem 0.125rem oklch(0.29 0.018 285 / 0.06),
    0 0.3125rem 0.875rem -0.1875rem oklch(0.72 0.12 152 / 0.4);

  --shadow-primary-hover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.6),
    inset 0 -0.0625rem 0.0625rem oklch(0.34 0.072 153 / 0.14),
    0 0.125rem 0.25rem oklch(0.29 0.018 285 / 0.07),
    0 0.5rem 1.25rem -0.1875rem oklch(0.72 0.12 152 / 0.5);

  /* ─── Chart palette: Amie's five pastel event hues. ─── */
  --chart-1: var(--pastel-green);
  --chart-2: var(--pastel-blue);
  --chart-3: var(--pastel-lavender);
  --chart-4: var(--pastel-pink);
  --chart-5: var(--pastel-yellow);

  /* --- Motion (standard profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 150ms;
  --transition-duration-base: 200ms;
  --transition-duration-slow: 280ms;
  --ease-out: cubic-bezier(0.165, 0.84, 0.44, 1);
  --ease-in-out: cubic-bezier(0.645, 0.045, 0.355, 1);
  --ease-in: cubic-bezier(0.55, 0.055, 0.675, 0.19);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-pastel-pink: var(--pastel-pink);
  --color-pastel-pink-foreground: var(--pastel-pink-foreground);
  --color-pastel-blue: var(--pastel-blue);
  --color-pastel-blue-foreground: var(--pastel-blue-foreground);
  --color-pastel-green: var(--pastel-green);
  --color-pastel-green-foreground: var(--pastel-green-foreground);
  --color-pastel-yellow: var(--pastel-yellow);
  --color-pastel-yellow-foreground: var(--pastel-yellow-foreground);
  --color-pastel-lavender: var(--pastel-lavender);
  --color-pastel-lavender-foreground: var(--pastel-lavender-foreground);

  --radius-sm: calc(var(--radius) - 0.375rem);
  --radius-md: calc(var(--radius) - 0.25rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.375rem);

  --shadow-s: var(--shadow-s);
  --shadow-m: var(--shadow-m);
  --shadow-l: var(--shadow-l);
  --shadow-inset: var(--shadow-inset);
  --shadow-button: var(--shadow-button);
  --shadow-button-hover: var(--shadow-button-hover);
  --shadow-primary: var(--shadow-primary);
  --shadow-primary-hover: var(--shadow-primary-hover);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: spacious;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 62);
  --layout-inset: calc(var(--spacing, 0.25rem) * 10);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 12);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 6);
}

